package com.wanyuecity.energy.operation;
import com.wanyuecity.energy.core.ApiResponse;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/operations/clearance-templates") public class OperationClearanceTemplateController{private final OperationClearanceTemplateService service;public OperationClearanceTemplateController(OperationClearanceTemplateService service){this.service=service;}@GetMapping@PreAuthorize("hasAnyRole('SUPER_ADMIN','SYSTEM_ADMIN','APPLICANT')")public ApiResponse<List<Map<String,Object>>>list(){return ApiResponse.ok(service.list());}@GetMapping("/stall/{token}")@PreAuthorize("hasAnyRole('SUPER_ADMIN','SYSTEM_ADMIN','APPLICANT','VIEWER')")public ApiResponse<Map<String,Object>>stall(@PathVariable String token){return ApiResponse.ok(service.resolveByToken(token));}@PostMapping@PreAuthorize("hasAnyRole('SUPER_ADMIN','SYSTEM_ADMIN')")public ApiResponse<Map<String,Object>>save(@RequestBody Map<String,Object>b,Authentication a){return ApiResponse.ok(service.save(b,a.getName()));}@PutMapping("/{id}/enable")@PreAuthorize("hasAnyRole('SUPER_ADMIN','SYSTEM_ADMIN')")public ApiResponse<Void>enable(@PathVariable Long id){service.enable(id);return ApiResponse.ok(null);}}
